1	// Supabase Edge Function: process-document
2	// OCR + AI extraction of medical documents (lab reports, prescriptions, discharge summaries).
3	// Receives an image URL, sends to Claude Vision, returns structured JSON.
4	//
5	// Deploy: npx supabase functions deploy process-document --project-ref ecywxuqhnlkjtdshpcbc
6	
7	import { serve } from "https://deno.land/std@0.177.0/http/server.ts";
8	
9	const SUPABASE_URL = "https://ecywxuqhnlkjtdshpcbc.supabase.co";
10	const ANON_KEY =
11	  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImVjeXd4dXFobmxranRkc2hwY2JjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM2MzQ2NTcsImV4cCI6MjA4OTIxMDY1N30.oo-x5L87FzJoprHIK8iFmHRa7AlIZlpDLg5Q1taY1Dg";
12	
13	const corsHeaders = {
14	  "Access-Control-Allow-Origin": "*",
15	  "Access-Control-Allow-Headers":
16	    "authorization, x-client-info, apikey, content-type",
17	  "Access-Control-Allow-Methods": "POST, OPTIONS",
18	};
19	
20	const PAD_SYSTEM_PROMPT = `You are a medical document transcription assistant for a pediatric hospital.`;
21	
22	const SYSTEM_PROMPT = `You are a medical document OCR assistant for a pediatric hospital in India. Extract structured data from medical documents (lab reports, prescriptions, discharge summaries, radiology reports).
23	
24	RETURN ONLY valid JSON (no markdown, no code fences) with this structure:
25	{
26	  "document_type": "lab_report|prescription|discharge_summary|radiology|other",
27	  "summary": "Comprehensive clinical summary of the ENTIRE document — include patient demographics, admission/discharge details, key clinical findings, course of treatment, investigations done, procedures performed, condition at discharge, and follow-up advice. This summary will be shown to the treating doctor as context. Write 3-6 sentences in clinical note style.",
28	  "lab_values": [
29	    {
30	      "test_name": "Hemoglobin",
31	      "value": "11.2",
32	      "unit": "g/dL",
33	      "flag": "normal|low|high|critical",
34	      "test_category": "Hematology|Biochemistry|Microbiology|Imaging",
35	      "reference_range": "11.5-16.5 g/dL",
36	      "report_date": "YYYY-MM-DD or null"
37	    }
38	  ],
39	  "diagnoses": ["diagnosis text"],
40	  "medications": [
41	    { "drug": "drug name", "dose": "250mg", "frequency": "TDS", "duration": "5 days" }
42	  ],
43	  "vaccinations": [
44	    { "vaccine_name": "BCG", "dose_number": 1, "date_given": "YYYY-MM-DD or null", "site": "left arm", "batch_no": "string or null" }
45	  ],
46	  "clinical_notes": "any other relevant clinical text from the document",
47	  "lab_name": "name of lab or hospital if visible",
48	  "report_date": "YYYY-MM-DD if date is visible, otherwise null"
49	}
50	
51	DOCUMENT-TYPE SPECIFIC RULES:
52	
53	For LAB REPORTS:
54	- Extract ALL lab values visible in the document.
55	
56	For DISCHARGE SUMMARIES:
57	- Lab values: extract ONLY the MOST RECENT / LATEST value for each test. Discharge summaries often contain serial monitoring values (e.g., 7 TSB readings across days). Return only the last one. Set report_date to the date that value was measured.
58	- Medications: extract only DISCHARGE medications (medications at the time of discharge / "medications on discharge" / "discharge advice"). Do NOT include historical in-hospital medications.
59	- Extract all diagnoses (primary + secondary).
60	
61	For PRESCRIPTIONS:
62	- Extract medications with dose, frequency, duration.
63	- Extract diagnoses if present.
64	
65	For VACCINATION CARDS / IMMUNIZATION RECORDS:
66	- Extract ALL vaccination entries visible: vaccine name, dose number, date given, site of injection, batch number.
67	- Normalize vaccine names to standard abbreviations: BCG, OPV, IPV, Hep B, DPT, DTwP, DTaP, Pentavalent, PCV, Rotavirus, MR, MMR, Typhoid, Hep A, Varicella, JE, Influenza, HPV, Td, TT.
68	- If multiple doses of same vaccine, list each as a separate entry with correct dose_number (1, 2, 3, booster).
69	- Date format: YYYY-MM-DD. If only month/year visible, use first day of month.
70	- Return empty vaccinations array [] for non-vaccination documents.
71	
72	TEST NAME NORMALIZATION — always use the standard name:
73	- Hb, Hemoglobin → Hemoglobin
74	- WBC, TLC, Total WBC → TLC (WBC)
75	- RBC, Total RBC → RBC Count
76	- PCV, HCT, Hematocrit → PCV/Hematocrit
77	- MCV → MCV
78	- MCH → MCH
79	- MCHC → MCHC
80	- PLT, Platelet, Platelet Count → Platelet Count
81	- ESR → ESR
82	- CRP → CRP
83	- ALT, SGPT → SGPT/ALT
84	- AST, SGOT → SGOT/AST
85	- ALP, Alkaline Phosphatase → ALP
86	- Bilirubin Total, T.Bil → Total Bilirubin
87	- Bilirubin Direct, D.Bil → Direct Bilirubin
88	- BUN, Blood Urea Nitrogen → BUN
89	- Creat, Creatinine, S.Creatinine → Serum Creatinine
90	- Na, Sodium → Sodium
91	- K, Potassium → Potassium
92	- Ca, Calcium → Calcium
93	- FBS, Fasting Blood Sugar, Fasting Glucose → Fasting Blood Sugar
94	- RBS, Random Blood Sugar → Random Blood Sugar
95	- HbA1c, Glycated Hb → HbA1c
96	- TSH → TSH
97	- T3, Total T3 → T3
98	- T4, Total T4 → T4
99	- Urine R/M, Urine Routine → Urine Routine
100	- TSB, Total Serum Bilirubin → Total Serum Bilirubin
101	
102	TEST CATEGORY — assign one of:
103	- "Hematology" — CBC, Hb, TLC, RBC, Platelets, ESR, blood film, coagulation
104	- "Biochemistry" — LFT, KFT, electrolytes, glucose, bilirubin, thyroid, CRP, HbA1c
105	- "Microbiology" — cultures, sensitivity, urine R/M, stool R/M, rapid tests
106	- "Imaging" — X-ray, USG, CT, MRI findings
107	
108	FLAGS:
109	- "normal" — within reference range
110	- "low" — below reference range
111	- "high" — above reference range
112	- "critical" — dangerously abnormal
113	
114	GENERAL RULES:
115	- If a value has a reference range printed, include it in reference_range and flag accordingly
116	- If the document is unclear or illegible, still return the JSON structure with empty arrays and note "partially legible" in summary
117	- Dates should be in YYYY-MM-DD format
118	- Return empty arrays [] for fields with no data (never omit fields)`;
119	
120	serve(async (req: Request) => {
121	  if (req.method === "OPTIONS") {
122	    return new Response("ok", { headers: corsHeaders });
123	  }
124	
125	  try {
126	    const ANTHROPIC_API_KEY = Deno.env.get("ANTHROPIC_API_KEY");
127	    if (!ANTHROPIC_API_KEY) {
128	      throw new Error("ANTHROPIC_API_KEY not configured.");
129	    }
130	
131	    const {
132	      image_url,
133	      image_base64,
134	      media_type: reqMediaType,
135	      patient_id,
136	      visit_id,
137	      category,
138	      doc_date,
139	      mode,
140	    } = await req.json();
141	
142	    if (!image_url && !image_base64) {
143	      return new Response(
144	        JSON.stringify({ error: "image_url or image_base64 is required" }),
145	        {
146	          status: 400,
147	          headers: { ...corsHeaders, "Content-Type": "application/json" },
148	        },
149	      );
150	    }
151	
152	    // Determine media type and build the content source for Claude
153	    let contentSource: any;
154	    let mediaType: string;
155	
156	    if (image_base64) {
157	      // Direct base64 from client (prescription pad attach flow — no storage)
158	      mediaType = reqMediaType || "image/jpeg";
159	      const isPdf = mediaType === "application/pdf";
160	      contentSource = {
161	        type: isPdf ? "document" : "image",
162	        source: {
163	          type: "base64",
164	          media_type: mediaType,
165	          data: image_base64,
166	        },
167	      };
168	    } else {
169	      // URL-based source — let Claude fetch directly (no chunked base64 conversion)
170	      // Detect media type from URL extension or HEAD request
171	      const urlLower = image_url.toLowerCase();
172	      const isPdf =
173	        urlLower.endsWith(".pdf") ||
174	        urlLower.includes("content-type=application/pdf");
175	      if (isPdf) {
176	        mediaType = "application/pdf";
177	        contentSource = {
178	          type: "document",
179	          source: { type: "url", url: image_url },
180	        };
181	      } else {
182	        mediaType = "image/jpeg"; // Claude auto-detects actual type from URL
183	        contentSource = {
184	          type: "image",
185	          source: { type: "url", url: image_url },
186	        };
187	      }
188	    }
189	
190	    // Build the user message with context
191	    const contextParts: string[] = [];
192	    if (category) contextParts.push(`Document category: ${category}`);
193	    if (doc_date) contextParts.push(`Document date: ${doc_date}`);
194	    if (patient_id) contextParts.push(`Patient ID: ${patient_id}`);
195	
196	    // For prescription pad mode, use a fast text-dump prompt instead of structured JSON
197	    const isPadMode = mode === "pad";
198	    const padPrompt = `This is a photo of a doctor's handwritten notes on a notepad. The handwriting may be messy, abbreviated, or use medical shorthand — this is normal.
199	
200	Your job: transcribe EXACTLY what is written. Do not summarize, interpret, rephrase, or add commentary. Output the text as-is, preserving the doctor's own words, abbreviations, and structure.
201	
202	Rules:
203	- Output ONLY the transcribed text, nothing else
204	- Keep the doctor's exact abbreviations (e.g., "c/o", "o/e", "Dx", "Rx", "Hb", "TLC", "BD", "TDS")
205	- Keep the doctor's exact phrasing and sentence fragments
206	- If a word is unclear, write your best guess — do not skip it
207	- Preserve line breaks as the doctor wrote them
208	- Do NOT add labels like "Patient:", "Diagnosis:", "Medicines:" unless the doctor wrote them
209	- Do NOT add "(HIGH)" or "(LOW)" or any flags
210	- Do NOT rearrange or reformat the content
211	- If it is a printed lab report or prescription (not handwritten), still just transcribe all the text verbatim`;
212	
213	    const userText = isPadMode
214	      ? padPrompt
215	      : contextParts.length
216	        ? `Extract all medical data from this document.\n\nContext: ${contextParts.join(", ")}`
217	        : "Extract all medical data from this document.";
218	
219	    // Use separate system prompt for pad mode
220	    const systemPrompt = isPadMode ? PAD_SYSTEM_PROMPT : SYSTEM_PROMPT;
221	
222	    // Call Claude Vision API (PDF support is GA — no beta header needed)
223	    const response = await fetch("https://api.anthropic.com/v1/messages", {
224	      method: "POST",
225	      headers: {
226	        "Content-Type": "application/json",
227	        "x-api-key": ANTHROPIC_API_KEY,
228	        "anthropic-version": "2023-06-01",
229	      },
230	      body: JSON.stringify({
231	        model: "claude-sonnet-4-20250514",
232	        max_tokens: 2048,
233	        system: systemPrompt,
234	        messages: [
235	          {
236	            role: "user",
237	            content: [
238	              contentSource,
239	              {
240	                type: "text",
241	                text: userText,
242	              },
243	            ],
244	          },
245	        ],
246	      }),
247	    });
248	
249	    if (!response.ok) {
250	      const err = await response.json().catch(() => ({}));
251	      console.error("Claude API error:", err);
252	      return new Response(
253	        JSON.stringify({
254	          error: "AI extraction failed",
255	          detail: err?.error?.message || "Unknown error",
256	        }),
257	        {
258	          status: 502,
259	          headers: { ...corsHeaders, "Content-Type": "application/json" },
260	        },
261	      );
262	    }
263	
264	    const data = await response.json();
265	    const rawText = data.content
266	      .filter((b: any) => b.type === "text")
267	      .map((b: any) => b.text)
268	      .join("")
269	      .trim();
270	
271	    console.log(
272	      `Document processed (${isPadMode ? "pad" : "structured"}) for ${patient_id || "unknown"}: ` +
273	        `${data.usage?.input_tokens || 0} in / ${data.usage?.output_tokens || 0} out tokens`,
274	    );
275	
276	    // Pad mode: return raw text for dumping into prescription pad textarea
277	    if (isPadMode) {
278	      return new Response(
279	        JSON.stringify({
280	          text_for_pad: rawText,
281	          summary: rawText.substring(0, 200),
282	        }),
283	        {
284	          status: 200,
285	          headers: { ...corsHeaders, "Content-Type": "application/json" },
286	        },
287	      );
288	    }
289	
290	    // Structured mode: parse JSON response
291	    let extracted;
292	    try {
293	      extracted = JSON.parse(rawText);
294	    } catch {
295	      const jsonMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)```/);
296	      if (jsonMatch) {
297	        extracted = JSON.parse(jsonMatch[1].trim());
298	      } else {
299	        // Return raw text as summary if JSON parsing fails
300	        return new Response(
301	          JSON.stringify({
302	            summary: rawText,
303	            lab_values: [],
304	            medications: [],
305	            diagnoses: [],
306	          }),
307	          {
308	            status: 200,
309	            headers: { ...corsHeaders, "Content-Type": "application/json" },
310	          },
311	        );
312	      }
313	    }
314	
315	    console.log(
316	      `Extracted: type=${extracted.document_type}, labs=${extracted.lab_values?.length || 0}, meds=${extracted.medications?.length || 0}`,
317	    );
318	
319	    // Server-side save: if patient_id, visit_id, and doc_url provided, save directly to DB
320	    const doc_url = image_url;
321	    if (patient_id && visit_id && !isPadMode) {
322	      const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
323	      if (!SERVICE_KEY)
324	        console.warn("SUPABASE_SERVICE_ROLE_KEY not set — DB writes may fail");
325	      const dbKey = SERVICE_KEY || ANON_KEY;
326	      const dbHeaders = {
327	        apikey: dbKey,
328	        Authorization: `Bearer ${dbKey}`,
329	        "Content-Type": "application/json",
330	        Prefer: "return=minimal",
331	      };
332	
333	      // Save lab values to lab_results table (only if test_name, value, and date are present)
334	      let savedCount = 0;
335	      let skippedLabs = 0;
336	      if (extracted.lab_values?.length) {
337	        for (const lab of extracted.lab_values) {
338	          // Skip incomplete records — don't pollute the database
339	          const testDate = lab.report_date || doc_date || null;
340	          if (!lab.test_name || !lab.value || !testDate) {
341	            skippedLabs++;
342	            continue;
343	          }
344	          try {
345	            const res = await fetch(`${SUPABASE_URL}/rest/v1/lab_results`, {
346	              method: "POST",
347	              headers: dbHeaders,
348	              body: JSON.stringify({
349	                patient_id,
350	                visit_id,
351	                test_name: lab.test_name,
352	                value: lab.value,
353	                value_numeric: isNaN(parseFloat(lab.value))
354	                  ? null
355	                  : parseFloat(lab.value),
356	                unit: lab.unit || null,
357	                flag: lab.flag || "normal",
358	                test_category: lab.test_category || null,
359	                reference_range: lab.reference_range || null,
360	                lab_name: extracted.lab_name || null,
361	                test_date: testDate,
362	                source: "ai_extracted",
363	              }),
364	            });
365	            if (res.ok) savedCount++;
366	            else console.warn("Lab save failed:", res.status);
367	          } catch (e: any) {
368	            console.warn("Lab save error:", e.message);
369	          }
370	        }
371	        console.log(
372	          `Saved ${savedCount}/${extracted.lab_values.length} lab results to DB` +
373	            (skippedLabs
374	              ? ` (${skippedLabs} skipped — missing test_name, value, or date)`
375	              : ""),
376	        );
377	      }
378	
379	      // Save extracted vaccinations to vaccinations table (only with vaccine_name and date)
380	      let vaxSavedCount = 0;
381	      let skippedVax = 0;
382	      if (extracted.vaccinations?.length) {
383	        for (const vax of extracted.vaccinations) {
384	          // Skip incomplete records — must have vaccine name and date to be useful
385	          if (!vax.vaccine_name || !vax.date_given) {
386	            skippedVax++;
387	            continue;
388	          }
389	          try {
390	            const res = await fetch(`${SUPABASE_URL}/rest/v1/vaccinations`, {
391	              method: "POST",
392	              headers: dbHeaders,
393	              body: JSON.stringify({
394	                patient_id,
395	                vaccine_name: vax.vaccine_name,
396	                dose_number: vax.dose_number || null,
397	                date_given: vax.date_given,
398	                site: vax.site || null,
399	                batch_number: vax.batch_no || null,
400	                given_by: "extracted_from_document",
401	                free_or_paid: "unknown",
402	              }),
403	            });
404	            if (res.ok) vaxSavedCount++;
405	            else console.warn("Vaccination save failed:", res.status);
406	          } catch (e: any) {
407	            console.warn("Vaccination save error:", e.message);
408	          }
409	        }
410	        console.log(
411	          `Saved ${vaxSavedCount}/${extracted.vaccinations.length} vaccination records to DB` +
412	            (skippedVax
413	              ? ` (${skippedVax} skipped — missing vaccine_name or date)`
414	              : ""),
415	        );
416	      }
417	
418	      // Update attached_documents with OCR summary
419	      if (doc_url) {
420	        try {
421	          const vRes = await fetch(
422	            `${SUPABASE_URL}/rest/v1/visits?id=eq.${visit_id}&select=attached_documents`,
423	            { headers: dbHeaders },
424	          );
425	          if (vRes.ok) {
426	            const vData = await vRes.json();
427	            const docs = vData[0]?.attached_documents || [];
428	            const docIdx = docs.findIndex((d: any) => d.url === doc_url);
429	            if (docIdx >= 0) {
430	              docs[docIdx].ocr_summary = extracted.summary || null;
431	              docs[docIdx].ocr_lab_count = extracted.lab_values?.length || 0;
