// Pre-computed OCR results (keyed by doc row index)
let _preOcrResults = {};
let _ocrPromises = [];

async function onDocFileSelected(idx) {
  const fileInput = document.getElementById("doc-file-" + idx);
  const file = fileInput?.files?.[0];
  if (!file) return;
  const cat = document.getElementById("doc-cat-" + idx)?.value || "other";
  const statusEl = document.getElementById("doc-ocr-status-" + idx);

  // Only run OCR for medical document categories
  if (!OCR_CATEGORIES.some((t) => cat.includes(t))) {
    if (statusEl) statusEl.textContent = "✓ File selected: " + file.name;
    return;
  }

  if (file.size > 10 * 1024 * 1024) {
    if (statusEl) statusEl.textContent = "⚠ File too large (max 10 MB)";
    return;
  }

  if (statusEl)
    statusEl.innerHTML =
      '<span style="color:var(--blue)">⏳ Reading document with AI...</span>';

  try {
    // Process image (compress) then convert to base64
    const processed = await processImage(file);
    const base64 = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result.split(",")[1]);
      reader.onerror = reject;
      reader.readAsDataURL(processed);
    });
    const isPdf = file.type === "application/pdf";
    const mediaType = isPdf ? "application/pdf" : file.type || "image/jpeg";

    // Call OCR with base64 directly (no Storage URL needed yet)
    const res = await fetch(SB + "/functions/v1/process-document", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + KEY,
      },
      body: JSON.stringify({
        image_base64: base64,
        media_type: mediaType,
        category: cat,
      }),
    });

    if (res.ok) {
      const data = await res.json();
      _preOcrResults[idx] = data;
      const labCount = data.lab_values?.length || 0;
      const summary = data.summary || "";
      if (statusEl)
        statusEl.innerHTML =
          '<span style="color:var(--green)">✓ AI extracted: ' +
          (summary ? esc(summary.substring(0, 80)) + "... " : "") +
          (labCount ? "(" + labCount + " lab values) " : "") +
          "</span>";
      console.log(
        "Pre-OCR complete for doc",
        idx,
        ":",
        summary.substring(0, 100),
      );
    } else {
      if (statusEl)
        statusEl.innerHTML =
          '<span style="color:var(--ink3)">✓ File selected (AI extraction skipped)</span>';
      console.warn("Pre-OCR failed:", res.status);
    }
  } catch (e) {
    if (statusEl)
      statusEl.innerHTML =
        '<span style="color:var(--ink3)">✓ File selected</span>';
    console.warn("Pre-OCR error:", e.message);
  }
}

async function uploadDocuments(patientId, visitId) {
  _ocrPromises = [];
  const uploaded = [];
  for (let i = 0; i < docUploadCount; i++) {
    const row = document.getElementById("doc-row-" + i);
    if (!row) continue;
    const fileInput = document.getElementById("doc-file-" + i);
    const file = fileInput?.files?.[0];
    if (!file) continue;
    const cat = document.getElementById("doc-cat-" + i)?.value || "other";
    const date = document.getElementById("doc-date-" + i)?.value || "";
    const desc = document.getElementById("doc-desc-" + i)?.value || "";
    if (file.size > 10 * 1024 * 1024) {
      console.warn("File too large:", file.name);
      continue;
    }
    try {
      // Process image (resize, enhance, compress) — skip for PDFs
      const processedFile = await processImage(file);
      const isPdf = file.type === "application/pdf";
      const ext = isPdf ? "pdf" : "jpg";
      const contentType = isPdf ? "application/pdf" : "image/jpeg";
      const path = `${patientId}/${visitId}/${cat}_${Date.now()}.${ext}`;
      const uploadRes = await fetch(
        SB + "/storage/v1/object/documents/" + path,
        {
          method: "POST",
          headers: {
            apikey: KEY,
            Authorization: "Bearer " + KEY,
            "Content-Type": contentType,
            "x-upsert": "true",
          },
          body: processedFile,
        },
      );
      if (uploadRes.ok) {
        const url = SB + "/storage/v1/object/public/documents/" + path;
        const docEntry = {
          category: cat,
          date,
          description: desc,
          filename: file.name,
          url,
          size_bytes: processedFile.size || file.size,
        };
        // Use pre-computed OCR if available (ran when file was selected)
        const preOcr = _preOcrResults[i];
        if (preOcr) {
          docEntry.ocr_summary = preOcr.summary || null;
          docEntry.ocr_lab_count = preOcr.lab_values?.length || 0;
          docEntry.ocr_diagnoses = preOcr.diagnoses || [];
          docEntry.ocr_medications = preOcr.medications || [];
          console.log("Using pre-computed OCR for:", file.name);
        }
        // Send to Edge Function for server-side DB save (lab results + OCR summary update)
        // Non-blocking — Edge Function saves directly to database
        // Skip if pre-OCR already succeeded (data is already in docEntry)
        if (!preOcr && OCR_CATEGORIES.some((t) => cat.includes(t))) {
          _ocrPromises.push(
            fetch(SB + "/functions/v1/process-document", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: "Bearer " + KEY,
              },
              body: JSON.stringify({
                image_url: url,
                patient_id: patientId,
                visit_id: visitId,
                category: cat,
                doc_date: date,
              }),
            })
              .then((r) => (r.ok ? r.json() : null))
              .catch((e) => console.warn("OCR skipped:", e.message)),
          );
        }
        uploaded.push(docEntry);
        console.log("Uploaded:", cat, file.name, "→", url);
      } else {
        const errText = await uploadRes.text().catch(() => "");
        console.error("Upload failed:", file.name, uploadRes.status, errText);
        showToast(
          "⚠ Upload failed: " + file.name + " (" + uploadRes.status + ")",
          true,
        );
      }
    } catch (e) {
      console.error("Upload error:", file.name, e.message);
      showToast("⚠ Upload error: " + file.name + " — " + e.message, true);
    }
  }
  return uploaded;
}

