function updateMicUI(recording, engine) {
  const btn = document.getElementById("mic-btn");
  const st = document.getElementById("mic-st");
  if (recording) {
    btn.className = "mic-btn rec";
    btn.innerHTML = '<span class="mic-dot"></span> Recording…';
    st.textContent =
      engine === "AI" ? "Listening — speak naturally…" : "Listening…";
  } else {
    btn.className = "mic-btn";
    btn.innerHTML = '<span class="mic-dot"></span> Dictate';
    st.textContent = "F2: toggle mic · F4 hold: push-to-talk";
  }
}

// ===== KEYBOARD SHORTCUTS: F2 = toggle mic, F4 = push-to-talk =====
let pushToTalkActive = false;
document.addEventListener("keydown", (e) => {
  // F2: Toggle dictation on/off
  if (e.key === "F2") {
    e.preventDefault();
    toggleVoice();
    return;
  }
  // F4: Push-to-talk (start on keydown, stop on keyup)
  if (e.key === "F4" && !pushToTalkActive) {
    e.preventDefault();
    pushToTalkActive = true;
    if (!isRec) startVoice();
    return;
  }
});
document.addEventListener("keyup", (e) => {
  if (e.key === "F4" && pushToTalkActive) {
    e.preventDefault();
    pushToTalkActive = false;
    if (isRec) stopVoice();
  }
});

/* ===== ATTACH IMAGE/PDF — AI extracts medical data and dumps to pad ===== */
async function handleAttachment(input) {
  const file = input.files?.[0];
  if (!file) return;
  input.value = ""; // reset for re-use

  const st = document.getElementById("mic-st");
  const ta = document.getElementById("pad-ta");
  st.textContent = "Processing attachment…";

  try {
    // Step 1: Read file as base64
    const base64 = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result.split(",")[1]);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });

    // Step 2: For images, compress via canvas first
    let finalBase64 = base64;
    let mediaType = file.type || "image/jpeg";
    if (file.type.startsWith("image/")) {
      st.textContent = "Optimizing image…";
      const compressed = await compressForVision(file);
      finalBase64 = compressed.base64;
      mediaType = "image/jpeg";
    }

    // Step 3: Send to Claude Vision via Edge Function
    st.textContent = "AI reading document…";
    const res = await fetch(SB + "/functions/v1/process-document", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + KEY,
      },
      body: JSON.stringify({
        image_base64: finalBase64,
        media_type: mediaType,
        patient_id: selectedPatient?.id || null,
        category: "attached",
        mode: "pad", // tells Edge Function to return text for pad, not structured JSON
      }),
    });

    if (!res.ok) throw new Error("AI processing failed (" + res.status + ")");
    const data = await res.json();

    // Step 4: Dump transcribed text directly into the prescription pad
    // Clean up whitespace: trim each line, remove all blank lines
    const cleanText = (t) =>
      t
        .split("\n")
        .map((l) => l.trim())
        .filter((l) => l.length > 0)
        .join(" ")
        .trim();
    if (data.text_for_pad) {
      const cleaned = cleanText(data.text_for_pad);
      ta.value = (ta.value ? ta.value + " " : "") + cleaned;
      st.textContent = "Notes added ✓";
    } else if (data.summary) {
      const cleaned = cleanText(data.summary);
      ta.value = (ta.value ? ta.value + " " : "") + cleaned;
      st.textContent = "Notes added ✓";
    } else {
      st.textContent = "Could not read the document";
    }
  } catch (e) {
    console.error("Attachment processing error:", e);
    st.textContent = "Attachment failed: " + e.message;
  }
  setTimeout(() => {
    st.textContent = "Tap to dictate, or type above";
  }, 5000);
}

async function compressForVision(file) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(img.src);
      const maxW = 1200; // Enough for OCR, keeps tokens low
      let w = img.width,
        h = img.height;
      if (w > maxW) {
        h = Math.round((h * maxW) / w);
        w = maxW;
      }
      const c = document.createElement("canvas");
      c.width = w;
      c.height = h;
      const ctx = c.getContext("2d");
      ctx.drawImage(img, 0, 0, w, h);
      // Light contrast enhancement for better OCR
      try {
        const id = ctx.getImageData(0, 0, w, h);
        const d = id.data;
        let sum = 0;
        for (let i = 0; i < d.length; i += 4)
          sum += 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
        const mid = sum / (d.length / 4);
        const k = 0.05;
        for (let i = 0; i < d.length; i += 4) {
          for (let ch = 0; ch < 3; ch++)
            d[i + ch] = Math.round(
              255 / (1 + Math.exp(-k * (d[i + ch] - mid))),
